from __future__ import annotations

from pathlib import Path

from rasa.core.channels.voice_stream.call_recording.recording_encoder import (
    RECORDING_CONTENT_TYPE,
)
from rasa.core.channels.voice_stream.call_recording.storages.base import (
    RecordingReference,
    _object_key,
)
from rasa.core.config.available_endpoints import RecordingConfig
from rasa.core.persistor import GCSPersistor


class GCSRecordingStorage:
    """GCS recording storage wrapper backed by the model persistor."""

    def __init__(self, config: RecordingConfig) -> None:
        if config.gcs is None:
            raise ValueError("GCS recording storage requires recordings.gcs config.")
        self._gcs_config = config.gcs
        self._persistor = GCSPersistor(bucket_name=self._gcs_config.bucket)

    def upload(
        self, source: Path, conversation_id: str, call_id: str
    ) -> RecordingReference:
        """Upload the recording to GCS and return its object location.

        Args:
            source: Path to the encoded recording file.
            conversation_id: Conversation identifier used in the object key.
            call_id: Call identifier used in the object key.

        Returns:
            Location of the uploaded recording.
        """
        key = _object_key(self._gcs_config.prefix, conversation_id, call_id)
        self._persistor.persist_file(
            file_key=key,
            file_path=str(source),
            content_type=RECORDING_CONTENT_TYPE,
        )
        return RecordingReference(
            provider="gcs",
            bucket=self._gcs_config.bucket,
            key=key,
            uri=f"gs://{self._gcs_config.bucket}/{key}",
            content_type=RECORDING_CONTENT_TYPE,
        )
